 if(action==='observe'){const better=sense.peers.filter(o=>o.mind?.successes>m.successes).sort((a,b)=>b.mind.successes-a.mind.successes)[0];if(better&&g.sociality>.3){const entries=Object.entries(better.mind.q).sort((a,b)=>b[1]-a[1]);for(const [key,val]of entries.slice(0,1+Math.floor(g.cognition*2)))m.q[key]=(m.q[key]||0)*.8+val*.2;m.learnedFrom++;this.sim.lifeways?.copy(better,c);const p=m.practice,t=better.mind.practice;if(t){for(let i=0;i<4;i++)p.materials[i]=clamp(p.materials[i]*.8+t.materials[i]*.2+(this.sim.random()-.5)*.035,-2,3);p.routes=[...p.routes,...t.routes.slice(-2).map(r=>({...r}))].slice(-8);p.sources=[...p.sources,better.id].slice(-6);p.copies++;}}c.state='Observando';c.target=null;c.think=2;return true;}
